<nav class="segments" aria-label="Textbausteingruppen"><?php foreach(['contributions'=>'Beiträge','invoices'=>'Rechnungen','donations'=>'Spenden'] as $key=>$label): ?><a class="<?= $section==='texts_'.$key?'active':'' ?>" href="<?= e(url(['view'=>'settings','tab'=>'texts','group'=>$key])) ?>"><?= $label ?></a><?php endforeach ?></nav>
<link rel="stylesheet" href="settings-text-preview.css?v=1"><nav class="text-preview-jumps" aria-label="Text und Vorschau"><a href="#text-controls">Text bearbeiten</a><a href="#text-preview">Muster ansehen</a></nav>
<form method="post" class="settings-form paper-layout text-preview-layout" data-settings-form data-text-preview-editor><?= csrf().hidden('action','settings-save').hidden('section',$section).hidden('version',$sv) ?>
<div class="paper-controls" id="text-controls"><div class="card settings-actions"><label>Vorlage bearbeiten<select class="form-control" name="preview_template"><?php foreach($sd as $key=>$template): ?><option value="<?= e($key) ?>" <?= $textPreviewKey===$key?'selected':'' ?>><?= e($templateLabels[$key]) ?></option><?php endforeach ?></select></label><button class="btn btn-outline theme-secondary secondary" name="intent" value="pdf">PDF-Muster herunterladen</button></div>
<?php foreach($sd as $key=>$template): ?><details class="card text-template" data-text-template="<?= e($key) ?>" open><summary><?= e($templateLabels[$key]) ?></summary><div class="template-body"><p class="muted"><?php if($key==='invoice'): ?>Betreff und Benachrichtigungstext stehen in der E-Mail-Vorschau. Einleitung und Schlusstext stehen im PDF-Muster darunter.<?php else: ?>Der Benachrichtigungstext erscheint in der Nachrichtenvorschau und im PDF-Muster. Den Betreff siehst du über der Nachricht.<?php endif ?> Variable auswählen und an der Cursorposition einfügen.</p><button type="button" class="btn btn-outline theme-secondary text-button" data-reset-template>Standard wiederherstellen</button><template data-default-template><?= e(json_encode(SettingsSchema::templates($section)[$key],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE)) ?></template>
<?php settingsField('subject',['Betreff','text',200,''],$template,'data['.$key.']');richField('data['.$key.'][message]','Benachrichtigungstext',(string)$template['message']);
if($key==='invoice'){richField('data['.$key.'][intro]','Einleitung',(string)$template['intro']);richField('data['.$key.'][closing]','Schlusstext',(string)$template['closing']);}else echo hidden('data['.$key.'][intro]',$template['intro']).hidden('data['.$key.'][closing]',$template['closing']);settingsField('attach_pdf',['Dokument-PDF als Anhang vormerken','checkbox',1,false],$template,'data['.$key.']'); ?>
</div></details><?php endforeach ?><div class="card settings-actions"><a href="<?= e(url(['view'=>'settings','tab'=>'texts','group'=>substr($section,6)])) ?>" class="btn btn-outline theme-secondary button secondary">Verwerfen</a><button class="btn btn-solid theme-primary" name="intent" value="save">Speichern</button><p class="muted">Die Vorschau verwendet Musterwerte. Versand, Lastschrifteinzug und Bescheinigungserstellung werden dadurch nicht ausgelöst.</p></div></div><aside class="paper-preview-area" id="text-preview"><div class="paper-preview-title"><strong>Livevorschau mit Musterwerten</strong></div><section class="card"><h2>Benachrichtigung</h2><h3 data-text-preview-subject><?= e($document['text']['subject']) ?></h3><div class="preview-message" data-text-preview-message><?= SettingsSchema::html($document['text']['message']) ?></div></section><?php require __DIR__.'/../Documents/document-preview.php'; ?><p class="muted">Nur eine Musteransicht. Es wird keine Nachricht versendet und kein Beleg ausgestellt. Speichern übernimmt die Textbausteine.</p></aside></form><script defer src="settings-text-preview.js?v=4"></script>
